<?php use App\Services\LegacyMigrationTrace; ?>
<section class="surface migration-employee-detail" aria-labelledby="migration-employee-heading">
    <div class="panel-header"><div><h2 id="migration-employee-heading"><?=e($employeeTrace['name'])?></h2><p>NIP <?=e($employeeTrace['nip'])?> · Bagian <?=e($employeeTrace['department'])?></p></div><?php if($employeeTrace['current_employee']):?><a class="btn btn-light btn-sm" href="<?=e(url('master/karyawan',['edit'=>$employeeTrace['current_employee']['id']]))?>">Lihat karyawan <?=icon('chevron')?></a><?php endif;?></div>
    <div class="panel-body pt-0">
