            <summary><span><strong><?=e($item['title'])?></strong><small class="code-text"><?=e($item['name'])?></small></span><span class="migration-record-state"><?=e(LegacyMigrationTrace::statusLabel($item['status']))?><?php if($item['traces']):?> · <?=count($item['traces'])?> baris<?php endif;?></span></summary>
            <div class="migration-record-content">
                <?php if($item['runtime_note']):?><p class="muted-small"><?=e($item['runtime_note'])?></p><?php endif;?>
