                <?php if(!$item['traces']):?><p class="mb-3"><?php if($item['status']==='source_empty'):?>Tabel ini tidak memiliki baris pada backup sumber.<?php elseif($item['status']==='source_absent'):?>Tabel ini tidak ditemukan pada arsip sumber.<?php else:?>Tidak ada baris sumber dengan <?=e($item['key'])?> <?=e($item['key_value'])?>.<?php endif;?></p><?php endif;?>
                <?php foreach($item['traces'] as $record):?><div class="migration-record-links"><span class="<?=$record['status']==='mapped'?'badge-verified':'badge-pending'?>"><?=e(LegacyMigrationTrace::statusLabel($record['status']))?></span><a href="<?=e($record['archive_url'])?>">Arsip baris <?=e($record['ordinal'])?> <?=icon('chevron')?></a><?php if($record['target_url']):?><a href="<?=e($record['target_url'])?>">Data saat ini <?=icon('chevron')?></a><?php endif;?></div>
                    <p class="migration-scroll-note">Geser tabel untuk melihat nilai tujuan dan status pencocokan.</p><div class="table-responsive"><table class="table app-table migration-comparison-table"><thead><tr><th>Kolom sumber → tujuan</th><th>Nilai sumber</th><th>Nilai saat ini</th><th>Pencocokan</th></tr></thead><tbody><?php foreach($record['fields'] as $field):?><tr><td><strong><?=e($field['label'])?></strong><small class="cell-subtitle code-text"><?=e($field['source_column'])?> → <?=e($field['target_column'] ?? 'arsip')?></small></td><td class="migration-value"><?=e(LegacyMigrationTrace::displayValue($field['source']))?></td><td class="migration-value"><?=e(LegacyMigrationTrace::displayValue($field['current']))?></td><td><span class="migration-field-state <?=$field['status']==='same'?'is-match':'is-different'?>"><?=e(LegacyMigrationTrace::statusLabel($field['status']))?></span></td></tr><?php endforeach;?></tbody></table></div>
                <?php endforeach;?>
                <?php if(!$item['traces'] && $item['local_rows']):?><p class="muted-small">Ada <?=count($item['local_rows'])?> baris lokal terkait yang dipertahankan. Baris ini tidak berasal dari pemetaan sumber yang ditampilkan.</p><p class="migration-scroll-note">Geser tabel untuk melihat nilai tujuan dan status pencocokan.</p><div class="table-responsive"><table class="table app-table migration-comparison-table"><thead><tr><th>Kolom lokal</th><th>Nilai saat ini</th></tr></thead><tbody><?php $localFields=App\Domain\MasterModules::all()[$item['target']]['fields'] ?? ['nip'=>'NIP','jumlah'=>'Jumlah'];foreach($item['local_rows'] as $localRow):foreach($localFields as $field=>$label):?><tr><td><?=e($label)?><small class="cell-subtitle code-text"><?=e($field)?></small></td><td class="migration-value"><?=e(LegacyMigrationTrace::displayValue($localRow[$field] ?? null))?></td></tr><?php endforeach;endforeach;?></tbody></table></div><?php endif;?>
                <div class="migration-record-links"><?php if($item['archive_url']):?><a href="<?=e($item['archive_url'])?>">Lihat tabel arsip <?=icon('chevron')?></a><?php endif;?><?php if($item['target_url']):?><a href="<?=e($item['target_url'])?>">Lihat master <?=icon('chevron')?></a><?php endif;?></div>
            </div>
        </details><?php endforeach;?>
        </div>
    </div>
</section>

<section class="surface" aria-labelledby="migration-transactions-heading"><div class="panel-header"><h2 id="migration-transactions-heading">Komponen transaksi historis</h2><span class="soft-badge"><?=count($employeeTrace['history'])?> transaksi sumber</span></div><div class="panel-body pt-0">
